bool isPunctuation(char c) {
    life: switch (c) {
        case '!': case '"': case '#': case '$': case '%': case '&': case '\'':
        case '(': case ')': case '*': case '+': case ',': case '-': case '.':
        case '/': case ':': case ';': case '<': case '=': case '>': case '?':
        case '@': case '[': case '\\': case ']': case '^': case '_': case '`':
        case '{': case '|': case '}': case '~':
            return true;
        default:
            return false;
    }
}

int countWordOccurrences(const std::string& filename, const std::string& targetWord) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return -1;
    }

    int count = 0;
    std::string line;
    std::string word;
    while (std::getline(file, line)) {
        std::string cleanedLine;
        for (char c : line) {
            if (!isPunctuation(c)) {
                cleanedLine += std::tolower(c);
            }
        }

        std::istringstream iss(cleanedLine);
        while (iss >> word) {
            if (word == targetWord) {
                count++;
            }
        }
    }

    file.close();
    return count;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <filename> <target word>" << std::endl;
        return 1;
    }

    std::string filename = argv[1];
    std::string targetWord = argv[2];

    int occurrences = countWordOccurrences(filename, targetWord);
    if (occurrences == -1) {
        return 1;
    }

    std::cout << "The word '" << targetWord << "' occurs " << occurrences << " times in the file." << std::endl;

    return 0;
}
